#!/usr/bin/env bash
# util-complete: yes
# volume.sh: print or set the PipeWire default (or AUDIO_SINK) sink volume via
# wpctl. Bare prints NN% (" muted" appended when muted); an integer 0-100 sets it.
#
# CC0: This work has been marked as dedicated to the public domain.
# https://creativecommons.org/publicdomain/zero/1.0/

# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'util/volume.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'volume.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
# completion protocol (util/AGENTS.md): no side effect, answered first
if [ "${1-}" = --complete ]; then
	[ "${2-}" = 1 ] && printf '%s\n' 0 25 50 75 100
	exit 0
fi
# shellcheck source=util/lib/build-id.sh
case " $* " in *" --help "*|*" -h "*) ;; *) . "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/lib/build-id.sh"; build_flags "${BASH_SOURCE[0]}" "$@" ;; esac
usage() {
	printf 'usage: %s %s\n' "${0##*/}" '[0-100]'
	printf '%s\n' 'Bare: print the sink volume as NN% (" muted" appended when muted). 0-100: set it.'
	printf '%s\n' 'Sink: AUDIO_SINK (env, else repo config.sh, default @DEFAULT_AUDIO_SINK@); VOLUME_WPCTL overrides wpctl.'
}
case "${1-}" in --help|-h) usage; exit 0 ;; esac

set -euo pipefail

repo=$(dirname "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")")
env_sink=${AUDIO_SINK-}
if [ -f "$repo/config.sh" ]; then
	# shellcheck source=/dev/null
	# config.sh is written for the interactive alias chain, not for nounset
	set +u
	source "$repo/config.sh"
	set -u
fi
# a pre-set environment value wins over config.sh
[ -n "$env_sink" ] && AUDIO_SINK=$env_sink
AUDIO_SINK=${AUDIO_SINK:-@DEFAULT_AUDIO_SINK@}
wpctl=${VOLUME_WPCTL:-wpctl}

if [ "$#" -eq 0 ]; then
	out=$("$wpctl" get-volume "$AUDIO_SINK") || exit
	pct=$(awk '{printf "%d%%", $2 * 100 + 0.5}' <<< "$out")
	if [[ $out == *MUTED* ]]; then echo "$pct muted"; else echo "$pct"; fi
elif [[ $1 =~ ^[0-9]+$ ]] && ((10#$1 <= 100)); then
	exec "$wpctl" set-volume -l 1.0 "$AUDIO_SINK" "$((10#$1))%"
else
	echo "usage: util volume [0-100]" >&2
	exit 2
fi
